def create_codemon(name, hp, attack, defense):
  return {
    "name": name,
    "hp": hp,
    "attack": attack,
    "defense": defense
  }

def calculate_damage(attacker, defender):
  damage = attacker["attack"] - defender["defense"]
  if damage < 5:
    damage = 5
  return damage

def apply_damage(codemon, damage):
  codemon["hp"] = codemon["hp"] - damage
  return codemon

def is_alive(codemon):
  if codemon["hp"] > 0:
    return True
  else:
    return False

aquachu = create_codemon("Aquachu", 100, 60, 30)
pyrochu = create_codemon("Pyrochu", 80, 60, 20)

print("=== BATTLE START ===")
print(f"{pyrochu['name']} attacks {aquachu['name']}!\n")

damage = calculate_damage(pyrochu, aquachu)
print(f"Damage dealt: {damage}")

aquachu = apply_damage(aquachu, damage)
print(f"{aquachu['name']} HP: {aquachu['hp']}")
print(f"{aquachu['name']} alive: {is_alive(aquachu)}")

