def create_codemon(nom, hp, attaque, defense):
  return {
    "nom": nom,
    "hp": hp,
    "attaque": attaque,
    "defense": defense
  }

def calculate_damage(attaquant, defenseur):
  degats = attaquant["attaque"] - defenseur["defense"]
  if degats < 5:
    degats = 5
  return degats

def apply_damage(codemon, degats):
  codemon["hp"] = codemon["hp"] - degats
  return codemon

def is_alive(codemon):
  if codemon["hp"] > 0:
    return True
  else:
    return False

aquachu = create_codemon("Aquachu", 100, 60, 30)
pyrochu = create_codemon("Pyrochu", 80, 60, 20)

print("=== DÉBUT DU COMBAT ===")
print(f"{pyrochu['nom']} attaque {aquachu['nom']} !\n")

degats = calculate_damage(pyrochu, aquachu)
print(f"Dégâts infligés : {degats}")

aquachu = apply_damage(aquachu, degats)
print(f"{aquachu['nom']} HP : {aquachu['hp']}")
print(f"{aquachu['nom']} vivant : {is_alive(aquachu)}")
